// The acceptance-file cases both readers must agree on: the board mod's test imports them and
// tests/adaptive/test_acceptance_fixtures.py reads this same file for the Stop gate's reader
// (scripts/provost_runtime/acceptance.py load()). A mod test can import only code files, so the
// list is JSON inside `export default`: keep it plain JSON, the Python test cuts it out by its brackets.
// Each case: name, text (the file's content, which may be invalid JSON), expected (the reading:
// malformed, closed, or open with each gate's id, kind and status) and, when the board knowingly
// differs, runtimeOnly: why.
export default [
  {"name": "open: all five kinds and all three statuses", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"m\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}, {\"id\": \"l\", \"kind\": \"live\", \"check\": \"c\", \"status\": \"fail\"}, {\"id\": \"v\", \"kind\": \"visual\", \"check\": \"c\", \"status\": \"pending\"}, {\"id\": \"r\", \"kind\": \"review\", \"check\": \"c\", \"status\": \"pass\"}, {\"id\": \"h\", \"kind\": \"human\", \"check\": \"c\", \"status\": \"pending\"}]}", "expected": {"reading": "open", "gates": [{"id": "m", "kind": "machine", "status": "pass"}, {"id": "l", "kind": "live", "status": "fail"}, {"id": "v", "kind": "visual", "status": "pending"}, {"id": "r", "kind": "review", "status": "pass"}, {"id": "h", "kind": "human", "status": "pending"}]}},
  {"name": "open: no gates", "text": "{\"task\": \"T\", \"gates\": []}", "expected": {"reading": "open", "gates": []}},
  {"name": "open: optional fields ranAt, evidence, source, tree, files with digest", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"m\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\", \"ranAt\": \"2026-11-13T01:02:03Z\", \"evidence\": \"12 passed\", \"source\": \"issue #1\", \"tree\": \"abc123\"}, {\"id\": \"r\", \"kind\": \"review\", \"check\": \"c\", \"status\": \"pass\", \"files\": [\"a.py\", \"b.py\"], \"digest\": \"def456\", \"source\": \"spec\"}]}", "expected": {"reading": "open", "gates": [{"id": "m", "kind": "machine", "status": "pass"}, {"id": "r", "kind": "review", "status": "pass"}]}},
  {"name": "open: tree of any type on a review or human gate", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"r\", \"kind\": \"review\", \"check\": \"c\", \"status\": \"pass\", \"tree\": 5}, {\"id\": \"h\", \"kind\": \"human\", \"check\": \"c\", \"status\": \"pass\", \"tree\": null}]}", "expected": {"reading": "open", "gates": [{"id": "r", "kind": "review", "status": "pass"}, {"id": "h", "kind": "human", "status": "pass"}]}},
  {"name": "open: human gate with files alone or digest alone", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"h1\", \"kind\": \"human\", \"check\": \"c\", \"status\": \"pass\", \"files\": [\"a.py\"]}, {\"id\": \"h2\", \"kind\": \"human\", \"check\": \"c\", \"status\": \"pass\", \"digest\": \"d\"}]}", "expected": {"reading": "open", "gates": [{"id": "h1", "kind": "human", "status": "pass"}, {"id": "h2", "kind": "human", "status": "pass"}]}},
  {"name": "open: extra top-level and gate fields are ignored", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"m\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\", \"note\": [1, 2]}], \"extra\": \"x\"}", "expected": {"reading": "open", "gates": [{"id": "m", "kind": "machine", "status": "pass"}]}},
  {"name": "open: a leading BOM is stripped", "text": "\ufeff{\"task\": \"T\", \"gates\": [{\"id\": \"m\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}]}", "expected": {"reading": "open", "gates": [{"id": "m", "kind": "machine", "status": "pass"}]}},
  {"name": "closed: a reason", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"m\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}, {\"id\": \"l\", \"kind\": \"live\", \"check\": \"c\", \"status\": \"pass\"}], \"closed\": \"merged in #12\"}", "expected": {"reading": "closed"}},
  {"name": "closed: a reason with a failed gate", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"m\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"fail\"}], \"closed\": \"dropped\"}", "expected": {"reading": "closed"}},
  {"name": "closed: a reason and no gates", "text": "{\"task\": \"T\", \"gates\": [], \"closed\": \"done\"}", "expected": {"reading": "closed"}},
  {"name": "malformed: closed empty", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}], \"closed\": \"\"}", "expected": {"reading": "malformed"}},
  {"name": "malformed: closed whitespace only", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}], \"closed\": \"  \\t\\n \"}", "expected": {"reading": "malformed"}},
  {"name": "malformed: closed not a string", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}], \"closed\": true}", "expected": {"reading": "malformed"}},
  {"name": "malformed: closed null", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}], \"closed\": null}", "expected": {"reading": "malformed"}},
  {"name": "malformed: closed with a bad gate", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"telepathy\", \"check\": \"c\", \"status\": \"pass\"}], \"closed\": \"done\"}", "expected": {"reading": "malformed"}},
  {"name": "malformed: unknown kind", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"m\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}, {\"id\": \"x\", \"kind\": \"telepathy\", \"check\": \"c\", \"status\": \"pass\"}, {\"id\": \"l\", \"kind\": \"live\", \"check\": \"c\", \"status\": \"pass\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: kind missing", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"check\": \"c\", \"status\": \"pass\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: kind not a string", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": [\"machine\"], \"check\": \"c\", \"status\": \"pass\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: id missing", "text": "{\"task\": \"T\", \"gates\": [{\"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: id empty", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: id blank", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \" \\t\\n\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: id not a string", "text": "{\"task\": \"T\", \"gates\": [{\"id\": 1, \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: check missing", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"status\": \"pass\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: check not a string", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": 1, \"status\": \"pass\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: status unknown", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"maybe\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: status missing", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: gates not a list", "text": "{\"task\": \"T\", \"gates\": {\"a\": 1}}", "expected": {"reading": "malformed"}},
  {"name": "malformed: gates missing", "text": "{\"task\": \"T\"}", "expected": {"reading": "malformed"}},
  {"name": "malformed: a gate is a string", "text": "{\"task\": \"T\", \"gates\": [\"a\"]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: a gate is null", "text": "{\"task\": \"T\", \"gates\": [null]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: a later gate is not an object", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"m\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}, 3]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: task not a string", "text": "{\"task\": 1, \"gates\": []}", "expected": {"reading": "malformed"}},
  {"name": "malformed: task missing", "text": "{\"gates\": []}", "expected": {"reading": "malformed"}},
  {"name": "malformed: not JSON", "text": "{ not json", "expected": {"reading": "malformed"}},
  {"name": "malformed: empty text", "text": "", "expected": {"reading": "malformed"}},
  {"name": "malformed: trailing comma", "text": "{\"task\": \"T\", \"gates\": [],}", "expected": {"reading": "malformed"}},
  {"name": "malformed: top level is a list", "text": "[{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\"}]}]", "expected": {"reading": "malformed"}},
  {"name": "malformed: top level is a string", "text": "\"just text\"", "expected": {"reading": "malformed"}},
  {"name": "malformed: top level is null", "text": "null", "expected": {"reading": "malformed"}},
  {"name": "malformed: evidence not a string", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\", \"evidence\": 5}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: ranAt not a string", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\", \"ranAt\": 5}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: source null", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\", \"source\": null}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: files without digest", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\", \"files\": [\"a.py\"]}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: digest without files", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\", \"digest\": \"d\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: files empty", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"r\", \"kind\": \"review\", \"check\": \"c\", \"status\": \"pass\", \"files\": [], \"digest\": \"d\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: files not a list", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"r\", \"kind\": \"review\", \"check\": \"c\", \"status\": \"pass\", \"files\": \"a.py\", \"digest\": \"d\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: files hold a non-string", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"r\", \"kind\": \"review\", \"check\": \"c\", \"status\": \"pass\", \"files\": [\"a.py\", 1], \"digest\": \"d\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: files hold an empty path", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"r\", \"kind\": \"review\", \"check\": \"c\", \"status\": \"pass\", \"files\": [\"a.py\", \"\"], \"digest\": \"d\"}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: digest not a string", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"r\", \"kind\": \"review\", \"check\": \"c\", \"status\": \"pass\", \"files\": [\"a.py\"], \"digest\": 1}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: tree not a string on a machine gate", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\", \"tree\": 1}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: tree not a string on a live gate", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"l\", \"kind\": \"live\", \"check\": \"c\", \"status\": \"pass\", \"tree\": [\"x\"]}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: tree not a string on a visual gate", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"v\", \"kind\": \"visual\", \"check\": \"c\", \"status\": \"pass\", \"tree\": null}]}", "expected": {"reading": "malformed"}},
  {"name": "malformed: a BOM and then bad JSON", "text": "\ufeff{ nope", "expected": {"reading": "malformed"}},
  {"name": "runtime only: ranAt not a time", "text": "{\"task\": \"T\", \"gates\": [{\"id\": \"a\", \"kind\": \"machine\", \"check\": \"c\", \"status\": \"pass\", \"ranAt\": \"yesterday\"}]}", "expected": {"reading": "malformed"}, "runtimeOnly": "the runtime parses ranAt with datetime.fromisoformat; the board only checks that it is a string"},
  {"name": "runtime only: a NaN literal", "text": "{\"task\": \"T\", \"gates\": [], \"note\": NaN}", "expected": {"reading": "open", "gates": []}, "runtimeOnly": "Python json accepts NaN, JSON.parse does not"}
]
